from evolving_agent.session import Deadline, ToolAgentSession
from evolving_agent.model import ModelReply, ToolCall
from evolving_agent.mcp_client import ToolOutcome
class Model:
 def __init__(self): self.calls=[]
 def reply(self, *, conversation, tools=()):
  self.calls.append((conversation, tools))
  if len(self.calls)==1: return ModelReply('', (ToolCall('x','work','{}'),), ({'type':'function_call','call_id':'x'},))
  return ModelReply('completed evidence-based answer', ())
class Tools:
 def call(self, name, arguments): return ToolOutcome(is_error=False, text='done')
m=Model(); outcome=ToolAgentSession(m, Tools(), deadline=Deadline(10), max_steps=2).run(instructions='system', opening='task')
assert outcome.finished and outcome.summary == 'completed evidence-based answer', outcome
assert outcome.steps == 2, outcome
assert len(m.calls) == 2 and m.calls[1][1] == (), m.calls
assert 'Tool-work budget is exhausted' in m.calls[1][0][-1]['content']
print('reserved final response verified:', outcome.reason)
